create or replace function public.has_org_role(org uuid,roles public.institute_role[]) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from public.organization_memberships m where m.organization_id=org and m.user_id=auth.uid() and m.status='active' and m.role=any(roles))$$;
create or replace function public.has_employer_role(org uuid,roles public.employer_role[]) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from public.employer_memberships m where m.organization_id=org and m.user_id=auth.uid() and m.status='active' and m.role=any(roles))$$;
create or replace function public.has_program_role(org uuid,roles text[]) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from public.program_memberships m where m.organization_id=org and m.user_id=auth.uid() and m.status='active' and m.role=any(roles))$$;
revoke all on function public.has_org_role(uuid,public.institute_role[]) from public;grant execute on function public.has_org_role(uuid,public.institute_role[]) to authenticated;revoke all on function public.has_employer_role(uuid,public.employer_role[]) from public;grant execute on function public.has_employer_role(uuid,public.employer_role[]) to authenticated;revoke all on function public.has_program_role(uuid,text[]) from public;grant execute on function public.has_program_role(uuid,text[]) to authenticated;
drop policy if exists "staff manage cohorts" on public.cohorts;create policy "authorized staff manage cohorts" on public.cohorts for all using(public.has_org_role(organization_id,array['owner','admin','placement_officer']::public.institute_role[])) with check(public.has_org_role(organization_id,array['owner','admin','placement_officer']::public.institute_role[]));
drop policy if exists "staff manage consented support" on public.learner_support_actions;create policy "authorized staff manage consented support" on public.learner_support_actions for all using(public.has_org_role(organization_id,array['owner','admin','placement_officer','faculty']::public.institute_role[])) with check(public.has_org_role(organization_id,array['owner','admin','placement_officer','faculty']::public.institute_role[]) and exists(select 1 from public.institute_data_grants g where g.organization_id=learner_support_actions.organization_id and g.learner_user_id=learner_support_actions.learner_user_id and g.purpose='education_support' and g.revoked_at is null and(g.expires_at is null or g.expires_at>now())));
drop policy if exists "employers manage access requests" on public.talent_access_requests;create policy "authorized employers manage access requests" on public.talent_access_requests for all using(public.has_employer_role(organization_id,array['owner','admin','recruiter']::public.employer_role[])) with check(public.has_employer_role(organization_id,array['owner','admin','recruiter']::public.employer_role[]) and requested_by=auth.uid());
drop policy if exists "members manage governance cases" on public.governance_cases;create policy "authorized members manage governance cases" on public.governance_cases for all using(public.has_program_role(program_organization_id,array['program_admin','auditor','grievance_officer'])) with check(public.has_program_role(program_organization_id,array['program_admin','auditor','grievance_officer']));
